public List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        generatePermutations(result, new ArrayList<>(), nums);
        return result;
    }

private void generatePermutations(List<List<Integer>> result, List<Integer> currentPermutation, int[] nums) {
        if (currentPermutation.size() == nums.length) {
            result.add(new ArrayList<>(currentPermutation));
            return;
        }

        for (int i = 0; i < nums.length; i++) {
            if (!currentPermutation.contains(nums[i])) {
                currentPermutation.add(nums[i]);
                generatePermutations(result, currentPermutation, nums);
                currentPermutation.remove(currentPermutation.size() - 1);
            }
        }
    }

public int findLargestSubstring(List<String> strings) {
    int maxSize = 0;

    for (String str : strings) {
        // Check if the middle part alone or its inverse is a substring of the original string
        for (int i = 0; i < str.length() / 2; i++) {
            if (str.substring(i).equals(str.substring(str.length() - i - 1)) ||
                str.substring(i).equals(reverse(str.substring(i)))) {
                maxSize = Math.max(maxSize, str.length());
            }
        }
    }

    return maxSize;
}

