public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a graph to represent the n-teresting space
    Map<Integer, Set<Integer>> graph = new HashMap<>();
    for (int i = 0; i < n * n; i++) {
        graph.put(i, new HashSet<>());
    }
    for (int[] path : paths) {
        int u = path[0];
        int v = path[1];
        graph.get(u).add(v);
        graph.get(v).add(u);
    }

    // Check if there is a path from start to end
    return findPath(n, n, start, end, graph) ? "can be travelled" : "cannot be travelled";
}

private static boolean findPath(int rows, int cols, int[] start, int[] end, Map<Integer, Set<Integer>> graph) {
    if (!graph.containsKey(start[0] * cols + start[1]) || !graph.containsKey(end[0] * cols + end[1])) {
        return false;
    }

    boolean[] visited = new boolean[rows * cols];
    return dfs(graph, start, end, 0, visited);
}

private static boolean dfs(Map<Integer, Set<Integer>> graph, int[] start, int[] end, int currNode, boolean[] visited) {
    if (visited[currNode]) {
        return false;
    }

    visited[currNode] = true;

    int row = currNode / cols;
    int col = currNode % cols;
    if (row == end[0] && col == end[1]) {
        return true;
    }

    // Explore adjacent cells
    for (int neighbor : graph.get(currNode)) {
        if (dfs(graph, start, end, neighbor, visited)) {
            return true;
        }
    }

    return false;
}

