public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int totalSum = 0;

    // Calculate the total sum of the array
    for (int num : nums) {
        totalSum += num;
    }

    // If the total sum is odd, it's impossible to split the array with the same average
    if (totalSum % n != 0) {
        return false;
    }

    // Find the average of each subarray
    int targetAverage = totalSum / n;
    boolean[] dp = new boolean[n];

    // Check if we can get the target average with any subarray
    for (int i = 0; i < n; i++) {
        dp[i] = dp[i - 1] || (i > 0 && nums[i - 1] == targetAverage);
    }

    // Check if we can get the target average starting from the first element
    for (int i = 1; i < n; i++) {
        if (dp[i - 1]) {
            if (nums[i] == targetAverage * (n - 1)) {
                return true;
            }
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return Math.min(cost[0], 0);
    }

    int [] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = Math.min(cost[0], cost[1]);

    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i-1] + cost[i], dp[i-2] + cost[i]);
    }

    return dp[n-1];
}

