public boolean hasAllCodes(String s, int k) {
    int required = (int) Math.pow(2, k);
    boolean[] exists = new boolean[required];
    int mask = 0;

    for (int i = 0; i < s.length(); i++) {
        mask <<= 1;
        if (s.charAt(i) == '1') mask |= 1;
        if (i >= k - 1) {
            exists[mask] = true;
            mask >>= 1;
        }
    }

    for (boolean b : exists) {
        if (!b) return false;
    }
    return true;
}

