public int maxAbsoluteSum(int[] nums) {
    int n = nums.length;
    int maxSum = 0;
    int minSum = 0;
    int currentMax = 0;
    int currentMin = 0;

    for(int num: nums){
        currentMax = Math.max(num, currentMax + num);
        currentMin = Math.min(num, currentMin + num);

        maxSum = Math.max(maxSum, currentMax);
        minSum = Math.min(minSum, currentMin);
    }

    return Math.max(maxSum, -minSum);
}

public int findMinFibonacciNumbers(int k) {
    int fibSeq[] = new int[30];
    fibSeq[1] = 1;
    fibSeq[2] = 1;

    for (int i = 3; i <= 29; i++) {
        fibSeq[i] = fibSeq[i - 1] + fibSeq[i - 2];
    }

    PriorityQueue<Integer> pq = new PriorityQueue<>();
    for (int i = 29; i >= 2; i--) {
        if (fibSeq[i] <= k) {
            pq.offer(fibSeq[i]);
        }
    }

    int count = 0;
    while (!pq.isEmpty() && k > 0) {
        if (k >= pq.peek()) {
            k -= pq.poll();
            count++;
        } else {
            break;
        }
    }

    return count;
}

public int kthFactor(int n, int k) {
        // Check if the kth factor exists in the range of factors of n
        if (k <= 1 || k > n) {
            return -1;
        }

        // Loop through the factors of n to find the kth factor
        int factorCount = 0;
        for (int i = 1; i <= n; i++) {
            if (n % i == 0) {
                factorCount++;
                if (factorCount == k) {
                    return i;
                }
            }
        }

        return -1; // Return -1 if the kth factor does not exist
    }

