public int maxUniqueSplit(String s) {
    int n = s.length();
    Set<String> seen = new HashSet<>();
    int maxUnique = 0;

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j <= n; j++) {
            String substring = s.substring(i, j);
            if (!seen.contains(substring)) {
                seen.add(substring);
                maxUnique++;
            } else {
                // reached a known substring, cannot split further
                break;
            }
        }
    }

    return maxUnique;
}

