                count = 0;
            }
            maxCount = Math.max(maxCount, count);
        }
    }

    // Check for diagonal lines (top-left to bottom-right)
    for (int i = 0, j = 0; i < mat.length && j < mat[0].length; i++, j++) {
        int count = 0;
        while (i < mat.length && j < mat[0].length && mat[i][j] == 1) {
            count++;
            i++;
            j++;
        }
        maxCount = Math.max(maxCount, count);
    }

    // Check for anti-diagonal lines (top-right to bottom-left)
    for (int i = 0, j = mat[0].length - 1; i < mat.length && j >= 0; i++, j--) {
        int count = 0;
        while (i < mat.length && j >= 0 && mat[i][j] == 1) {
            count++;
            i++;
            j--;
        }
        maxCount = Math.max(maxCount, count);
    }

    return maxCount;
}

