public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] leftSmaller = findSmaller(heights, n);
    int[] rightSmaller = findSmaller(heights, n);

    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        int width = rightSmaller[i] - leftSmaller[i] - 1;
        maxArea = Math.max(maxArea, width * heights[i]);
    }
    return maxArea;
}

private static int[] findSmaller(int[] heights, int n) {
    Stack<Integer> stack = new Stack<>();
    int[] smaller = new int[n];

    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        smaller[i] = stack.isEmpty() ? -1 : stack.peek();
        stack.push(i);
    }

    return smaller;
}

public static int[] diagonalOrder(int[][] mat) {
    int rows = mat.length;
    int cols = mat[0].length;

    int totalElements = rows * cols;
    int[] result = new int[totalElements];
    int index = 0;

    // For each row
    for (int i = 0; i < rows; i++) {
        int r = i;
        int c = 0;

        while (r >= 0 && c < cols) {
            result[index++] = mat[r][c];
            r--;
            c++;
        }

        // Move to the next col if the row went off
        if (r < 0) {
            while (c < cols) {
                result[index++] = mat[0][c];
                c++;
            }
            break;
        }
    }

    // For each col
    for (int j = 1; j < cols; j++) {
        int r = rows - 1;
        int c = j;

        while (r >= 0 && c < cols) {
            result[index++] = mat[r][c];
            r--;
            c++;
        }

        // Move to the next col if the row went off
        if (c < cols) {
            while (r >= 0) {
                result[index++] = mat[r][cols - 1];
                r--;
            }
            break;
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    int digits[] = new int[10];
    int temp = n;

    // Count the occurrence of each digit in n
    while (temp > 0) {
        digits[temp % 10]++;
        temp /= 10;
    }

    for (int i = 0; i < 10; i++) {
        // If there is more than one occurrence of a digit, swap the digits
        for (int j = i + 1; j < 10; j++) {
            if (digits[j] > 0) {
                int tempDigit = digits[i];
                digits[i] = digits[j];
                digits[j] = tempDigit;

                // Reconstruct the smallest integer
                int result = 0;
                for (int k = 0; k < 10; k++) {
                    result = result * 10 + digits[k];
                }

                // Check if the result is greater than n and not equal to n
                if (result > n && result != n) {
                    return result;
                }

                // If the current digit is greater than the next digit, swap back and continue
                digits[i] = tempDigit;
                digits[j] = temp;
            }
        }
    }

    // If no solution is found, return -1
    return -1;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }

    for (int i = 1; i <= Math.sqrt(n); i++) {
        int left = i;
        int right = n - i - 1;

        String leftStr = String.valueOf(left);
        String rightStr = String.valueOf(right);

        StringBuilder center = new StringBuilder();
        for (int j = 0; j < i; j++) {
            center.append(leftStr.charAt(j));
            center.append(rightStr.charAt(j));
        }

        result.add(center.toString());
    }

    return result;
}

public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check if the area of the triangle formed by any three points is zero
    return (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) != 0;
}

