public static int calculateEnergy(String s) {
    int maxEnergy = 0;
    int currentEnergy = 0;

    for (int i = 0; i < s.length(); i++) {
        currentEnergy++;
        if (i == s.length() - 1 || s.charAt(i) != s.charAt(i + 1)) {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 0;
        }
    }

    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
    LinkedList<Integer> list = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        list.add(i);
    }
    while(list.peek() <= n) {
        for (int j = 9; j >= 0; j--) {
            int top = list.peek(); list.poll();
            if (top / 10 * 10 + j <= n) {
                list.add(top / 10 * 10 + j);
            }
            top = list.peek(); list.poll(); list.add(top * 10 + j);
        }
    }
    return list;
}

public static int calculateUniqueSum(int[] nums) {
    int sum = 0;
    Set<Integer> seen = new HashSet<>();
    for (int num : nums) {
        if (!seen.contains(num)) {
            seen.add(num);
            sum += num;
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    char[] chars = s.toCharArray();
    for (int i = 0; i < chars.length; i++) {
        int a = i;
        int b = i;
        while (b < chars.length - 1 && chars[b] != ' ') b++;
        while (a < b) {
            char temp = chars[a];
            chars[a] = chars[b];
            chars[b] = temp;
            a++;
            b--;
        }
    }
    return new String(chars);
}
